import{c as a,Q as l,j as o,m as s}from"./chunks/framework.rWdQudnF.js";const h=JSON.parse('{"title":"设备管理","description":"","frontmatter":{"title":"设备管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/设备管理.md","filePath":"综合知识/系统基础/操作系统/设备管理.md","lastUpdated":null}'),r={name:"综合知识/系统基础/操作系统/设备管理.md"};function e(i,t,d,n,c,p){return l(),o("div",null,[...t[0]||(t[0]=[s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 设备分类</li><li>[ ] I/O 软件与典型流程</li><li>[ ] SPOOLING 技术</li><li>[ ] 缓冲区技术（单/双/循环/缓冲池）</li><li>[ ] 中断处理</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="设备分类" tabindex="-1">设备分类 <a class="header-anchor" href="#设备分类" aria-label="Permalink to &quot;设备分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类维度</th><th>类型</th></tr></thead><tbody><tr><td>按数据组织</td><td>块设备、字符设备</td></tr><tr><td>按设备功能</td><td>输入/输出/存储/网络联网/供电设备</td></tr><tr><td>按资源分配</td><td>独占设备、共享设备、虚拟设备</td></tr><tr><td>按传输速率</td><td>低速/中速/高速设备</td></tr></tbody></table><h3 id="i-o-软件" tabindex="-1">I/O 软件 <a class="header-anchor" href="#i-o-软件" aria-label="Permalink to &quot;I/O 软件&quot;">​</a></h3><blockquote><p>🎯 一句话结论：I/O 软件<strong>隐藏了 I/O 操作实现的细节</strong>，方便用户使用 I/O 设备。</p></blockquote><p>典型流程：用户程序读文件 → 与设备无关软件检查缓存 → 若无则调用设备驱动 → 向 I/O 硬件发请求 → 用户进程阻塞 → 磁盘操作完成 → 硬件产生中断 → 中断处理程序唤醒用户进程。</p><h3 id="spooling-技术" tabindex="-1">SPOOLING 技术 <a class="header-anchor" href="#spooling-技术" aria-label="Permalink to &quot;SPOOLING 技术&quot;">​</a></h3><blockquote><p>🎯 一句话结论：SPOOLING 在外设建立输入井/输出井，实现<strong>物理设备虚拟化</strong>，多进程感觉独占使用。</p></blockquote><p>在外设上建立两个数据缓冲区（输入井/输出井），多个进程共用一台独占设备（如打印机），数据排队存储在缓冲区中自动按序处理，实现<strong>物理设备的虚拟化</strong>，每个进程感觉独占使用。</p><h3 id="缓冲区技术" tabindex="-1">缓冲区技术 <a class="header-anchor" href="#缓冲区技术" aria-label="Permalink to &quot;缓冲区技术&quot;">​</a></h3><blockquote><p>🎯 一句话结论：四种缓冲区 — 单缓冲、双缓冲、循环缓冲、缓冲池。<strong>双缓冲</strong>允许一个缓冲区填满后立即切换到另一个，提高并行性。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>单缓冲</td><td>仅一个缓冲区，I/O 设备与 CPU 交替等待</td></tr><tr><td>双缓冲</td><td>两个缓冲区交替使用，一个填满时切换到另一个，提高并行性</td></tr><tr><td>循环缓冲</td><td>多个缓冲区构成环形队列，循环使用</td></tr><tr><td>缓冲池</td><td>系统统一管理的大量缓冲区</td></tr></tbody></table><p>缓冲区的<strong>目的</strong>：缓和 CPU 和 I/O 速度不匹配、减少 CPU 中断频率、提高并行性。⚠️ 缓冲区<strong>不能增加系统存储容量</strong>。</p><h3 id="中断处理" tabindex="-1">中断处理 <a class="header-anchor" href="#中断处理" aria-label="Permalink to &quot;中断处理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：CPU 响应中断时断点信息保存到<strong>栈</strong>中，不是通用寄存器、堆或 I/O 接口。</p></blockquote><p>嵌入式系统采用中断方式输入输出的原因：让 CPU 不用轮询等待 I/O 设备，提高 CPU 效率。</p><p><strong>缺页中断</strong>：CPU 访问的页不在物理内存但存在于磁盘 → 触发缺页中断 → 处理过程称为<strong>页面置换</strong>。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q60] 缓冲区</strong></p><p>在计算机系统中引入缓冲区的主要目的不包括以下哪一项（ ）。</p><ul><li>A. 缓和CPU和I/O设备速度不匹配的矛盾</li><li>B. 减少对CPU的中断频率</li><li>C. 提高CPU和I/O设备之间的并行性</li><li>D. 增加系统的存储容量</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：缓冲区不增加存储容量，目的是速度匹配、减少中断、提高并行性。</p></div></details><hr><p><strong>[Q61] 双缓冲</strong></p><p>在操作系统中，以下哪种缓冲区类型允许在一个缓冲区被填满后立即切换到另一个缓冲区，从而提高I/O操作的效率（ ）。</p><ul><li>A. 单缓冲</li><li>B. 双缓冲</li><li>C. 循环缓冲</li><li>D. 缓冲池</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：双缓冲=两个缓冲区交替使用，一个填满立即切另一个，实现I/O与CPU并行。</p></div></details><hr><p><strong>[Q62] 流水线</strong></p><p>某流水线系统有5个功能段，每段执行时间分别为2ns、3ns、1ns、4ns、2ns。若该系统需要连续处理100条指令，则总执行时间为（ ）。</p><ul><li>A. 416ns</li><li>B. 408ns</li><li>C. 420ns</li><li>D. 424ns</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：流水线周期=最长段=4ns。总时间=ΣΔt + (n-1)×周期 = 12 + 99×4 = 408ns。</p></div></details>',34)])])}const b=a(r,[["render",e]]);export{h as __pageData,b as default};
